class Solution { static ArrayList<Integer>list=new ArrayList<>(); static ArrayList<List<Integer>>ans=new ArrayList<>(); public List<List<Integer>> combinationSum3(int k, int n) { ans.clear(); list.clear(); int []arr={1,2,3,4,5,6,7,8,9}; findSolution(0,0,k,n,arr); return ans; } public static void findSolution(int index,int currentSum,int k,int target,int [] arr){ if(currentSum==target){ if(list.size()==k && !ans.contains(list)){ ans.add(new ArrayList<>(list)); } return; } if(currentSum>target||index>=arr.length){ return; } list.add(arr[index]); findSolution(index+1,currentSum+arr[index],k,target,arr); list.remove(list.size()-1); findSolution(index+1,currentSum,k,target,arr); } }
